() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  if (target) {
    target.scrollIntoView({ behavior: 'instant', block: 'start' });
    return { scrolled: true, text: target.textContent.trim() };
  }
  return { scrolled: false };
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  // climb up to a container that contains all 3 chart cards (h4 headings)
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) {
    sec = sec.parentElement;
  }
  const r = sec.getBoundingClientRect();
  return {
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    docHeight: document.documentElement.scrollHeight,
    sectionTag: sec.tagName,
    sectionClass: (sec.className || '').toString().slice(0, 120),
    h4Count: sec.querySelectorAll('h4').length,
    rect: { top: Math.round(r.top), left: Math.round(r.left), width: Math.round(r.width), height: Math.round(r.height) },
    scrollY: Math.round(window.scrollY)
  };
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
  // find scrollable ancestor
  let sc = sec.parentElement;
  const chain = [];
  while (sc && sc !== document.body) {
    const cs = getComputedStyle(sc);
    chain.push({
      tag: sc.tagName,
      cls: (sc.className || '').toString().slice(0, 80),
      overflowY: cs.overflowY,
      scrollH: sc.scrollHeight,
      clientH: sc.clientHeight
    });
    sc = sc.parentElement;
  }
  return chain;
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
  const modified = [];
  const mod = (el, fn) => { modified.push([el, el.style.cssText]); fn(el); };
  // 1) expand overflow/height-restricted ancestors
  let el = sec.parentElement;
  while (el && el !== document.documentElement) {
    const cs = getComputedStyle(el);
    if (cs.overflowY !== 'visible' || cs.overflowX !== 'visible' || cs.height.endsWith('px') && el.classList.contains('h-screen') || cs.maxHeight !== 'none' || el.classList.contains('h-screen')) {
      mod(el, e => {
        e.style.setProperty('overflow', 'visible', 'important');
        e.style.setProperty('overflow-y', 'visible', 'important');
        e.style.setProperty('height', 'auto', 'important');
        e.style.setProperty('max-height', 'none', 'important');
        e.style.setProperty('flex', 'none', 'important');
      });
    }
    el = el.parentElement;
  }
  // 2) hide siblings before charts section inside report container
  const report = sec.parentElement;
  for (const child of Array.from(report.children)) {
    if (child === sec) break;
    mod(child, e => e.style.setProperty('display', 'none', 'important'));
  }
  // 3) hide siblings before report container
  const wrap = report.parentElement;
  for (const child of Array.from(wrap.children)) {
    if (child === report) break;
    mod(child, e => e.style.setProperty('display', 'none', 'important'));
  }
  window.__diagRestore = () => { modified.forEach(([e, css]) => { e.style.cssText = css; }); };
  const r = sec.getBoundingClientRect();
  return {
    modifiedCount: modified.length,
    docHeight: document.documentElement.scrollHeight,
    secRect: { top: Math.round(r.top + window.scrollY), width: Math.round(r.width), height: Math.round(r.height) },
    innerWidth: window.innerWidth
  };
}

() => {
  if (window.__diagRestore) { window.__diagRestore(); delete window.__diagRestore; }
  const h3s = Array.from(document.querySelectorAll('h3'));
