    svgSize: sr ? { w: Math.round(sr.width), h: Math.round(sr.height) } : null,
    docHeight: document.documentElement.scrollHeight
  };
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
  const modified = [];
  const mod = (el, fn) => { modified.push([el, el.style.cssText]); fn(el); };
  // ancestors needing expansion: scroll div, MAIN, flex-row div, h-screen div
  const targets = [];
  let el = sec.parentElement;
  while (el && el !== document.documentElement) {
    const cs = getComputedStyle(el);
    if (cs.overflowY !== 'visible' || el.classList.contains('h-screen')) targets.push(el);
    el = el.parentElement;
  }
  targets.forEach(e => {
    const w = e.getBoundingClientRect().width;
    mod(e, x => {
      x.style.setProperty('overflow', 'visible', 'important');
      x.style.setProperty('height', 'auto', 'important');
      x.style.setProperty('max-height', 'none', 'important');
      x.style.setProperty('width', w + 'px', 'important');
      x.style.setProperty('flex', '0 0 auto', 'important');
    });
  });
  // hide siblings before charts section inside report container
  const report = sec.parentElement;
  for (const child of Array.from(report.children)) {
    if (child === sec) break;
    mod(child, e => e.style.setProperty('display', 'none', 'important'));
  }
  const wrap = report.parentElement;
  for (const child of Array.from(wrap.children)) {
    if (child === report) break;
    mod(child, e => e.style.setProperty('display', 'none', 'important'));
  }
  window.__diagRestore = () => { modified.forEach(([e, css]) => { e.style.cssText = css; }); };
  const r = sec.getBoundingClientRect();
  return {
    modifiedCount: modified.length,
    docHeight: document.documentElement.scrollHeight,
    secRect: { topDoc: Math.round(r.top + window.scrollY), width: Math.round(r.width), height: Math.round(r.height) }
  };
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
  const secTop = sec.getBoundingClientRect().top + window.scrollY;
  // find visible elements between 0 and secTop that take vertical space
  const all = Array.from(document.querySelectorAll('body *'));
  const above = [];
  for (const e of all) {
    const r = e.getBoundingClientRect();
    const top = r.top + window.scrollY;
    if (r.height > 100 && top < secTop - 50 && r.width > 100 && top + r.height > 100) {
      const cs = getComputedStyle(e);
      if (cs.display !== 'none' && r.height < 3000) {
        above.push({ tag: e.tagName, cls: (e.className || '').toString().slice(0, 60), top: Math.round(top), h: Math.round(r.height), w: Math.round(r.width) });
      }
    }
  }
  // keep only leaf-ish big blocks (dedupe ancestors)
  return { secTop: Math.round(secTop), blocks: above.slice(-15) };
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
  const report = sec.parentElement;
  const wrap = report.parentElement;
  const scrollDiv = wrap.parentElement;
  const info = (e) => ({ cls: (e.className || '').toString().slice(0, 70), display: getComputedStyle(e).display, h: Math.round(e.getBoundingClientRect().height) });
  return {
    reportChildrenCount: report.children.length,
    reportChildren: Array.from(report.children).map(info),
    wrapChildren: Array.from(wrap.children).map(info),
    scrollChildren: Array.from(scrollDiv.children).map(info)
  };
}

() => {
  const h3s = Array.from(document.querySelectorAll('h3'));
  const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
  let sec = target;
  while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
  const scrollDiv = sec.parentElement.parentElement.parentElement;
  const builder = scrollDiv.children[0];
  const old = builder.style.cssText;
  builder.style.setProperty('display', 'none', 'important');
  const prevRestore = window.__diagRestore;
  window.__diagRestore = () => { builder.style.cssText = old; prevRestore(); };
  const r = sec.getBoundingClientRect();
  window.scrollTo(0, 0);
  return { docHeight: document.documentElement.scrollHeight, secTop: Math.round(r.top + window.scrollY), secH: Math.round(r.height), secW: Math.round(r.width) };
}

() => {
  if (window.__diagRestore) { window.__diagRestore(); delete window.__diagRestore; }
  return new Promise(resolve => setTimeout(() => {
    const h3s = Array.from(document.querySelectorAll('h3'));
    const target = h3s.find(h => h.textContent.includes('可视化报表图表'));
    let sec = target;
    while (sec && sec.querySelectorAll('h4').length < 3 && sec.parentElement) sec = sec.parentElement;
    const r = sec.getBoundingClientRect();
    resolve({ restored: true, secW: Math.round(r.width), secH: Math.round(r.height), docHeight: document.documentElement.scrollHeight });
  }, 600));
}

() => {
  const svgs = Array.from(document.querySelectorAll('svg.recharts-surface'));
  return svgs.map((s, i) => {
    const r = s.getBoundingClientRect();
    return { i, w: Math.round(r.width), h: Math.round(r.height), vw: s.getAttribute('viewBox'), wAttr: s.getAttribute('width'), hAttr: s.getAttribute('height') };
  });
}

() => {
  const cards = Array.from(document.querySelectorAll('h4')).filter(h => h.textContent.includes('走势') || h.textContent.includes('结构'));
  return cards.map(h => {
    const card = h.closest('div.bg-slate-950');
    return { title: h.textContent.trim(), hasSvg: !!(card && card.querySelector('svg.recharts-surface')), svgCount: card ? card.querySelectorAll('svg.recharts-surface').length : 0 };
  });
}
